You can use a simple search algorithm, like in the following example:

import java.util.Scanner;

public class Search {
private static double search(double target, double min, double max, double epsilon) {
Scanner in = new Scanner(System.in);
System.out.print("Enter target: ");
double targetInput = in.nextDouble();
if (targetInput == target) {
System.out.println("Target found at: " + min + " with accuracy " + epsilon);
System.exit(0);
}
System.out.print("Enter min: ");
double minInput = in.nextDouble();
if (targetInput == target) {
System.out.println("Target found at: " + min + " with accuracy " + epsilon);
System.exit(0);
}
System.out.print("Enter max: ");
double maxInput = in.nextDouble();
if (targetInput == target) {
System.out.println("Target found at: " + min + " with accuracy " + epsilon);
System.exit(0);
}
double bestResult = Double.NaN;
for (double i = min; i < max; i = i + epsilon) {
if (!Double.isNaN(bestResult)) {
double searchResult = search(target, min, i, epsilon);
if (searchResult > bestResult) {
bestResult = searchResult;
}
}
}
System.out.println("Best result found at: " + min + " with accuracy " + epsilon);
return bestResult;
}

public static void main(String[] args) {
double target = 2020.2;
double min = 1;
double max = 1000000;
double epsilon = 1;
System.out.println("Target: " + target);
System.out.println("Min: " + min);
System.out.println("Max: " + max);
System.out.println("Epsilon: " + epsilon);
search(target, min, max, epsilon);
}

