#include <iostream>
#include <string>
#include <sstream>
using namespace std;

bool isPowerOfTen(int value) {
stringstream str(value);
str >> value;
return (value > 0 && value == 1 || value > 1 && value % 10 == 0);
}

int main() {
int value = 1;
int exponent = 0;

while (value > 0) {
if (isPowerOfTen(value)) {
cout << "The nearest power of ten to " << value << " is 10^" << exponent << endl;
return 0;
}
value /= 10;
exponent++;
}
return 0;
}

